head.script:
scwin.onpageload = function () {
    var paramData = $p.getParameter("HomeSearch");
    if (paramData.name != "") {
        searchboxOK.setValue(paramData.name)
        scwin.requestSearch();
    } else {
        btnFilterALL.addClass("on");
    }
};

scwin.searchDetail = function (realIndex) {
    // $p.log(rowIndex + columnId + columnId);
	const type = searchResult.getCellData(realIndex, "type");
    if (type == "section") { return}
    const title = searchResult.getCellData(realIndex, "label");
    const id = searchResult.getCellData(realIndex, "id");

    var rowJSON = {
        // "Personal Info": { "Name": "Lee", "Age": 50, "Married": false },
        // "Region": "Seoul",
        // "Carrier": true,
        "name": title,
        "id": id
    };

    // 새로 열릴 화면에 데이터를 전달 (dataObject를 통해 전달 가능)
    var obj = {
        "dataObject": {
            "type": "json",
            "name": "LeftSearch",
            "data": rowJSON
        }
    };

    scwin.setContentsSrc(type, obj);
};

scwin.setContentsSrc = async function (type, obj) {
    if (type === "biz") {
        await $p.parent().wfmRightContents.setSrc("/page/component/search/SystemSearchResultBizDetail.xml", obj);
    } else if (type === "scrn") {
        await $p.parent().wfmRightContents.setSrc("/page/component/search/SystemSearchResultScreenDetail.xml", obj);
    } else if (type === "tr") {
        await $p.parent().wfmRightContents.setSrc("/page/component/search/SystemSearchResultTRDetail.xml", obj);
    } else if (type === "db") {
        await $p.parent().wfmRightContents.setSrc("/page/component/search/SystemSearchResultDBDetail.xml", obj);
    } else if (type === "emp") {
        await $p.parent().wfmRightContents.setSrc("/page/component/search/SystemSearchResultMemberDetail.xml", obj);
    }
};

scwin.requestSearch = function () {
    unitTasks.removeAll();
    scrns.removeAll();
    svcs.removeAll();
    tables.removeAll();
    emps.removeAll();

    const maxCount = 30;

    if (searchboxOK.getValue() != "") {

        const baParam = {
            offset: 0,
            limit: maxCount,
            type: "PAGE",
            sortMethod: "NO",
            searchMethods: ["CONTAINS"],
            sortFields: ["unitAfrsName"],
            searchFields: ["unitAfrsName"/*, "chrrName", "manlName"*/],
            searchContent: searchboxOK.getValue()
        };

        $c.sbm.execute(sbmUnitTaskSearchList, baParam);


        const screenParam = {
            offset: 0,
            limit: maxCount,
            type: "PAGE",
            sortMethod: "NO",
            searchMethods: ["CONTAINS"],
            sortFields: ["scrnNo"],
            searchFields: ["scrnNo", "scrnName"/*, "dvlpChrrName", "witfChrrName"*/],
            searchContent: searchboxOK.getValue()
        };

        $c.sbm.execute(sbmTaskScreenList, screenParam);


        const trParam = {
            offset: 0,
            limit: maxCount,
            type: "PAGE",
            sortMethod: "NO",
            searchMethods: ["CONTAINS"],
            sortFields: ["svcCd"],
            searchFields: ["svcCd", "korSvcName"/*, "itChrrName"*/],
            searchContent: searchboxOK.getValue()
        };

        $c.sbm.execute(sbmServiceList, trParam);


        const tablesParam = {
            offset: 0,
            limit: maxCount,
            type: "PAGE",
            sortMethod: "NO",
            searchMethods: ["CONTAINS"],
            sortFields: ["tblEngName"],
            searchFields: ["tblEngName", "tblKorName"/*, "itChrrName"*/],
            searchContent: searchboxOK.getValue()
        };

        $c.sbm.execute(sbmTableList, tablesParam);


        const memberParam = {
            offset: 0,
            limit: maxCount,
            type: "PAGE",
            sortMethod: "NO",
            searchMethods: ["CONTAINS"],
            sortFields: ["empName"],
            searchFields: ["empName", "empNo"],
            searchContent: searchboxOK.getValue()
        };

        $c.sbm.execute(sbmEmpSearchList, memberParam);
    }
};

// 검색 결과 선택
scwin.gridBASearchResult_oncellclick = function (rowIndex, columnIndex, columnId) {
    const realIndex = gridBASearchResult.getRealRowIndex(rowIndex);
    scwin.searchDetail(realIndex);
};

scwin.resetBtnFontWeight = function () {
    btnFilterALL.removeClass("on");
    btnFilterBA.removeClass("on");
    btnFilterAAScreen.removeClass("on");
    btnFilterAATR.removeClass("on");
    btnFilterDA.removeClass("on");
    btnFilterMember.removeClass("on");

}

scwin.btnFilterALL_onclick = function (e) {
    scwin.resetBtnFontWeight();
    btnFilterALL.addClass("on");
};

scwin.btnFilterBA_onclick = function (e) {
    scwin.resetBtnFontWeight();
    btnFilterBA.addClass("on");
};

scwin.btnFilterAAScreen_onclick = function (e) {
    scwin.resetBtnFontWeight();
    btnFilterAAScreen.addClass("on");

};

scwin.btnFilterAATR_onclick = function (e) {
    scwin.resetBtnFontWeight();
    btnFilterAATR.addClass("on");

};

scwin.btnFilterDA_onclick = function (e) {
    scwin.resetBtnFontWeight();
    btnFilterDA.addClass("on");

};

scwin.btnFilterMember_onclick = function (e) {
    scwin.resetBtnFontWeight();
    btnFilterMember.addClass("on");

};

scwin.searchboxOK_onkeyup = function (e) {
    scwin.requestSearch();
    $p.log(searchboxOK.getValue());
};

scwin.sbmEmpIdInfo_submitdone = function (e) {

};

// 담당자
scwin.sbmEmpSearchList_submit = function (e) {

};

scwin.sbmEmpSearchList_submitdone = function (e) {
    // var jsoninfo1 = JSON.stringify(common.getJSON());
    // var jsoninfo2 = JSON.stringify(pageInfo.getJSON());
    // var jsoninfo3 = JSON.stringify(emps.getAllArray());
    // alert("done" + jsoninfo3);
    const rowIndex = searchResult.getRowIndexByStatus("member");
    searchResult.setRowArray(rowIndex, data, true);
};

scwin.sbmEmpSearchList_submiterror = function (e) {
    alert("error" + e.responseBody);
};


// 업무
scwin.sbmUnitTaskSearchList_submit = function (e) {
    scwin.mergeResult();
};

scwin.sbmUnitTaskSearchList_submitdone = function (e) {
    // var jsoninfo3 = JSON.stringify(unitTasks.getAllArray());
    // alert("done" + jsoninfo3);
};

scwin.sbmUnitTaskSearchList_submiterror = function (e) {
    alert("error" + e.responseBody);
};

// 테이블
scwin.sbmTableList_submitdone = function (e) {
    // var jsoninfo3 = JSON.stringify(tables.getAllArray());
    // alert("done" + jsoninfo3);
    scwin.mergeResult();
};

// 서비스
scwin.sbmServiceList_submitdone = function (e) {
    scwin.mergeResult();
};

// 화면
scwin.sbmTaskScreenList_submitdone = function (e) {
    scwin.mergeResult();
};

scwin.mergeResult = function () {
    searchResult.removeAll();

    var obj = [
        {
            "depth": 1,
            "label": "업무",
            "value": "",
            "path": "pathpath",
            "type": "section",
            "rowStatus": "",
            "id": ""
        }
    ];

    // 전체 row 수 가져오기
    for (let i = 0; i < unitTasks.getRowCount(); i++) {
        const unitAfrsName = unitTasks.getCellData(i, "unitAfrsName");
        const id = unitTasks.getCellData(i, "unitAfrsId");
        obj.push({
            depth: 2,  // 첫 번째만 depth 1
            label: unitAfrsName || "",  // unitAfrsName null이면 빈 문자열
            value: unitAfrsName + unitAfrsName,  // 예시 그대로 유지
            path: "",
            rowStatus: "",
            type: "biz",
            id: id
        });
    }

    obj.push(
        {
            "depth": 1,
            "label": "화면",
            "value": "",
            "path": "pathpath",
            "rowStatus": "",
            "type": "section",
            "id": ""
        }
    );

    // 전체 row 수 가져오기
    for (let i = 0; i < scrns.getRowCount(); i++) {
        const scrnNo = scrns.getCellData(i, "scrnNo");
        const scrnName = scrns.getCellData(i, "scrnName");
        const id = scrns.getCellData(i, "arfsScrnId");

        obj.push({
            depth: 2,  // 첫 번째만 depth 1
            label: scrnNo + " - " + scrnName || "",  // scrnName null이면 빈 문자열
            value: "",
            path: "",
            rowStatus: "",
            type: "scrn",
            id: id
        });
    }

    obj.push(
        {
            "depth": 1,
            "label": "TR",
            "value": "",
            "path": "pathpath",
            "type": "section",
            "rowStatus": "",
            "id": ""
        }
    );

    // 전체 row 수 가져오기
    for (let i = 0; i < svcs.getRowCount(); i++) {
        const svcCd = svcs.getCellData(i, "svcCd");
        const korSvcName = svcs.getCellData(i, "korSvcName");
        const id = svcs.getCellData(i, "svcId");

        obj.push({
            depth: 2,  // 첫 번째만 depth 1
            label: svcCd + " - " + korSvcName || "",  // sysName null이면 빈 문자열
            value: "",  // 예시 그대로 유지
            path: "",
            rowStatus: "",
            type: "tr",
            id: id
        });
    }

    obj.push(
        {
            "depth": 1,
            "label": "DB",
            "value": "",
            "path": "pathpath",
            "type": "section",
            "rowStatus": "",
            "id": ""
        }
    );

    // 전체 row 수 가져오기
    for (let i = 0; i < tables.getRowCount(); i++) {
        const tblEngName = tables.getCellData(i, "tblEngName");
        const tblKorName = tables.getCellData(i, "tblKorName");
        const id = tables.getCellData(i, "tlbId");

        obj.push({
            depth: 2,  // 첫 번째만 depth 1
            label: tblEngName + " - " + tblKorName || "",  // tblKorName null이면 빈 문자열
            value: "",  // 예시 그대로 유지
            path: "",
            rowStatus: "",
            type: "db",
            id: id
        });
    }

    obj.push(
        {
            "depth": 1,
            "label": "담당자",
            "value": "",
            "path": "pathpath",
            "type": "section",
            "rowStatus": "",
            "id": ""
        }
    );

    // 전체 row 수 가져오기
    for (let i = 0; i < emps.getRowCount(); i++) {
        const empNo = emps.getCellData(i, "empNo");
        const empName = emps.getCellData(i, "empName");
        const id = emps.getCellData(i, "empId");
        obj.push({
            depth: 2,  // 첫 번째만 depth 1
            label: empNo + " - " + empName || "",  // empName null이면 빈 문자열
            value: "",  // 예시 그대로 유지
            path: "",
            rowStatus: "",
            type: "emp",
            id: id
        });
    }

    searchResult.setJSON(obj, false);

}
